user_prompt:
method find_closest_elements(numbers: seq<real>) returns (closest: (real, real))
    requires |numbers| >= 2
    ensures closest == (min(a, b), max(a, b)) 
        where a, b: real :: a in numbers && b in numbers && abs(a - b) == minAbsDiff(numbers)
{
    // Implementation will go here
}

problem_data.canonical_solution:
closest_pair = None
distance = None

for idx, elem in enumerate(numbers):
    for idx2, elem2 in enumerate(numbers):
        if idx != idx2:
            if distance is None:
                distance = abs(elem - elem2)
                closest_pair = tuple(sorted([elem, elem2]))
            else:
                new_distance = abs(elem - elem2)
                if new_distance < distance:
                    distance = new_distance
                    closest_pair = tuple(sorted([elem, elem2]))

return closest_pair
